// ── Validate Emergency Accept Payload ───────────────────────────────────
const inputItem = $input.first().json || {};
const headers = inputItem.headers || {};
const body = inputItem.body || (inputItem.headers ? {} : inputItem);

const requestId = body.request_id || body.requestId;
if (!requestId || typeof requestId !== 'string') {
  return [{
    json: {
      isValid: false,
      statusCode: 400,
      error_code: 'INVALID_PAYLOAD',
      error: 'Missing or invalid request_id: must be a valid emergency request UUID'
    }
  }];
}

const respondingHospitalId = body.responding_hospital_id || body.hospital_id || '9c948e9d-16f5-4927-b67f-44e8bc928f62';
const correlationId = body.correlation_id || headers['x-correlation-id'] || `ACCEPT-${Date.now()}`;
const dispatchId = `dsp-${Date.now()}-${Math.random().toString(36).substring(2, 7)}`;

return [{
  json: {
    ...body,
    request_id: requestId,
    responding_hospital_id: respondingHospitalId,
    correlation_id: correlationId,
    dispatch_id: dispatchId,
    isValid: true,
    statusCode: 200
  }
}];

// Generate Signed Dispatch Pass
const prev = $('Validate Accept Payload').item.json;
const dispatchId = prev.dispatch_id;
const reqId = prev.request_id;
const issuedAt = new Date().toISOString();
const exp = new Date(Date.now() + 60 * 60 * 1000).toISOString();

const raw = `${dispatchId}:${reqId}:${issuedAt}`;
const crypto = require('crypto');
const secret = 'medconnect-secret';
let signature = '';
try {
  signature = crypto.createHmac('sha256', secret).update(raw).digest('hex');
} catch (e) {
  signature = 'SIG-' + Math.random().toString(36).substring(2, 10);
}

return [{
  json: {
    success: true,
    status: 'ACCEPTED_AND_LOCKED',
    request_id: reqId,
    dispatch_id: dispatchId,
    correlation_id: prev.correlation_id,
    pass: {
      dispatch_id: dispatchId,
      request_id: reqId,
      issued_at: issuedAt,
      exp: exp,
      signature: signature
    }
  }
}];
